// Reproducible public-data/Leaflet bundle. No runtime CDN JavaScript.
// Usage: node scripts/build-ocean-atlas.mjs [--local]
import fs from 'node:fs/promises';
import path from 'node:path';
import os from 'node:os';
import { execFileSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { NetCDFReader } from 'netcdfjs';
import { packTemperatureMonth } from '../src/features/oceanAtlas/model.js';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const out = path.join(root, 'src/features/oceanAtlas/data');
await fs.mkdir(out, { recursive: true });
const temp = await fs.mkdtemp(path.join(os.tmpdir(), 'dmz-atlas-'));
const urls = {
  temperature: 'https://downloads.psl.noaa.gov/Datasets/noaa.ersst.v5/sst.mon.ltm.1991-2020.nc',
  sites: 'https://floridakeys.noaa.gov/mbuoy/mooringBuoyLatLong.gpx.zip',
};
const local = process.argv.includes('--local');
async function get(name, filename, localPath) {
  if (local) return fs.readFile(localPath);
  const dest = path.join(temp, filename);
  execFileSync('curl', ['--fail', '-L', '--max-time', '90', '-o', dest, urls[name]], { stdio: 'inherit' });
  return fs.readFile(dest);
}
const [sstBytes, siteBytes] = await Promise.all([
  get('temperature', 'sst.nc', '/tmp/dmz-sst-climatology.nc'),
  get('sites', 'sites.zip', '/tmp/dmz-moorings.zip'),
]);
const nc = new NetCDFReader(sstBytes);
const latitudes = nc.getDataVariable('lat');
const longitudes = nc.getDataVariable('lon');
const values = nc.getDataVariable('sst');
const period = nc.variables.find(v => v.name === 'time').attributes.find(a => a.name === 'climo_period').value;
if (period !== '1991/01/01 - 2020/12/31' || values.length !== 12 * 89 * 180) throw new Error('Unexpected NOAA grid or baseline');
const grid = {
  source: 'NOAA ERSSTv5 / PSL', sourceUrl: urls.temperature, baseline: '1991–2020',
  resolution: 2, latitudes, longitudes,
  // Tenths of a degree Celsius, packed losslessly (model.packTemperatureMonth); null is missing/land, never zero.
  packing: 'tenths+20 base89 v1',
  packedMonths: Array.from({ length: 12 }, (_, m) => packTemperatureMonth(Array.from(values.slice(m * 89 * 180, (m + 1) * 89 * 180), v => Number.isFinite(v) && v >= -2 && v <= 45 ? Math.round(v * 10) : null))),
};
await fs.writeFile(path.join(out, 'temperature.json'), JSON.stringify(grid));
execFileSync(process.execPath, [path.join(root, 'scripts/build-ocean-coastline.mjs'), ...(local ? ['/tmp/dmz-land-10m.geojson'] : [])], { stdio: 'inherit' });
const zip = path.join(temp, 'moorings.zip');
await fs.writeFile(zip, siteBytes);
const xml = execFileSync('unzip', ['-p', zip, 'mooringBuoyLatLong.gpx'], { encoding: 'utf8' });
const groups = new Map();
for (const match of xml.matchAll(/<wpt lon="([^"]+)" lat="([^"]+)">\s*<name>([^<]+)<\/name>/g)) {
  const name = match[3].replace(/\s*\(Shipwreck Trail\)/g, '').replace(/\s+\d+\s*$/, '').trim();
  const points = groups.get(name) || [];
  points.push({ latitude: Number(match[2]), longitude: Number(match[1]) });
  groups.set(name, points);
}
const sites = [...groups].map(([name, points]) => ({
  id: `noaa-fknms-${name.toLowerCase().replace(/[^a-z0-9]+/g, '-')}`,
  name, ...points[0], region: 'Florida Keys', country: 'US',
  siteType: /wreck|bibb|duane|eagle|spiegel|thunderbolt|vandenberg/i.test(name) ? 'wreck' : 'reef',
  coordinateQuality: 'published mooring', buoyCount: points.length,
  sources: [{ sourceName: 'NOAA Florida Keys National Marine Sanctuary', sourceUrl: 'https://floridakeys.noaa.gov/mbuoy/allmbuoys.html', dataLicense: 'US government public data', sourceRecordId: name }],
  note: 'Published mooring location, not an entry recommendation. Source file dated February 2014; verify current access and buoy status locally.',
}));
if (sites.length < 20) throw new Error('NOAA site parsing returned too few sites');
await fs.writeFile(path.join(out, 'sites.json'), JSON.stringify(sites));
const js = await fs.readFile(path.join(root, 'node_modules/leaflet/dist/leaflet.js'), 'utf8');
const css = await fs.readFile(path.join(root, 'node_modules/leaflet/dist/leaflet.css'), 'utf8');
await fs.writeFile(path.join(out, 'leaflet.js'), `// Generated by scripts/build-ocean-atlas.mjs; Leaflet 1.9.4, BSD-2-Clause.\nexport const leafletJs = ${JSON.stringify(js.replace(/\/\/# sourceMappingURL=.*$/m, ''))};\nexport const leafletCss = ${JSON.stringify(css)};\n`);
await fs.copyFile(path.join(root, 'node_modules/leaflet/LICENSE'), path.join(out, 'LEAFLET-LICENSE.txt'));
execFileSync(process.execPath, [path.join(root, 'scripts/bundle-ocean-atlas-runtime.cjs')], { stdio: 'inherit' });
console.log(`Ocean Atlas: ${sites.length} NOAA sites; 12 × 89 × 180 SST cells; bundled land and Leaflet.`);
